//! The built-in widget runtimes this build embeds: each one's `runtime.json`
//! (contract 2, beside its source in `embed-runtime/src/<name>/`) and its
//! host document (generated by `npm run build:runtimes`). Every list of
//! built-in kinds derives from this table.

use crate::runtimes::{self, RuntimeManifest};
use std::sync::OnceLock;

/// One embedded runtime.
pub struct Builtin {
    /// `<name>@<major>`, as a widget names it.
    pub reference: &'static str,
    pub manifest: RuntimeManifest,
    pub host: &'static str,
}

impl std::fmt::Debug for Builtin {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.reference)
    }
}

/// Ref, manifest and host of each built-in. Literal paths: the licence
/// boundary test (`tests/embed_boundary.rs`) checks every one.
const EMBEDDED: [(&str, &str, &str); 4] = [
    (
        "model@1",
        include_str!("../../../embed-runtime/src/model/runtime.json"),
        include_str!("../../../embed-runtime/built/model/index.html"),
    ),
    (
        "video@1",
        include_str!("../../../embed-runtime/src/video/runtime.json"),
        include_str!("../../../embed-runtime/built/video/index.html"),
    ),
    (
        "table@1",
        include_str!("../../../embed-runtime/src/table/runtime.json"),
        include_str!("../../../embed-runtime/built/table/index.html"),
    ),
    (
        "chart@1",
        include_str!("../../../embed-runtime/src/chart/runtime.json"),
        include_str!("../../../embed-runtime/built/chart/index.html"),
    ),
];

/// Every built-in, in the order above. An embedded manifest that does not
/// parse is a build defect the tests catch, so it panics.
pub fn all() -> &'static [Builtin] {
    static ALL: OnceLock<Vec<Builtin>> = OnceLock::new();
    ALL.get_or_init(|| {
        EMBEDDED
            .iter()
            .map(|&(reference, manifest, host)| Builtin {
                reference,
                manifest: runtimes::parse_builtin(reference, manifest)
                    .unwrap_or_else(|e| panic!("{e}")),
                host,
            })
            .collect()
    })
}

pub fn by_ref(reference: &str) -> Option<&'static Builtin> {
    all().iter().find(|b| b.reference == reference)
}

pub fn by_name(name: &str) -> Option<&'static Builtin> {
    all().iter().find(|b| b.manifest.name == name)
}

/// The host document of the built-in `reference` names.
pub(crate) fn host(reference: &str) -> Option<&'static str> {
    by_ref(reference).map(|b| b.host)
}

